import { type PostgresRunner, postgres } from "@flue/postgres";
import type { PersistenceAdapter } from "@flue/runtime/adapter";
import pg from "pg";
import { setUnsettledSubmissionsProbe } from "./persistence-probe";

export type RouarPersistenceOptions = {
	/** Connection string. Defaults to `DATABASE_URL`. */
	connectionString?: string;
	/** Extra options passed to the `pg` pool. */
	pool?: Omit<pg.PoolConfig, "connectionString">;
};

function createRunner(options: RouarPersistenceOptions): PostgresRunner {
	let pool: pg.Pool | undefined;
	// Pool は最初の問い合わせで作る。import しただけでは接続しない
	const getPool = (): pg.Pool => {
		if (pool) return pool;
		const connectionString =
			options.connectionString ?? process.env.DATABASE_URL;
		if (!connectionString) {
			throw new Error(
				"[rouar] DATABASE_URL is not set. Run `rouar env pull` for local development.",
			);
		}
		pool = new pg.Pool({ connectionString, ...options.pool });
		return pool;
	};
	return {
		query: async (text, params) => (await getPool().query(text, params)).rows,
		// プール経由の接続先は transaction モードなので、
		// トランザクションは 1 つの接続の上で BEGIN から COMMIT までを流す
		transaction: async (fn) => {
			const client = await getPool().connect();
			try {
				await client.query("BEGIN");
				const result = await fn({
					query: async (text, params) =>
						(await client.query(text, params)).rows,
				});
				await client.query("COMMIT");
				return result;
			} catch (error) {
				await client.query("ROLLBACK").catch(() => undefined);
				throw error;
			} finally {
				client.release();
			}
		},
		close: async () => {
			const current = pool;
			pool = undefined;
			await current?.end();
		},
	};
}

/**
 * Creates the Flue Postgres persistence adapter backed by the rouar database.
 * Once connected, the server entry can ask whether any submissions are still unsettled.
 */
export function rouarPersistence(
	options: RouarPersistenceOptions = {},
): PersistenceAdapter {
	const adapter = postgres(createRunner(options));
	return {
		...(adapter.migrate ? { migrate: () => adapter.migrate?.() } : {}),
		async connect() {
			const stores = await adapter.connect();
			setUnsettledSubmissionsProbe(() =>
				stores.submissionStore.hasUnsettledSubmissions(),
			);
			return stores;
		},
		async close() {
			setUnsettledSubmissionsProbe(undefined);
			await adapter.close?.();
		},
	};
}

/** Default adapter, used from `db.ts` as `export { default } from "@rouar/sdk/db"`. */
const persistence: PersistenceAdapter = rouarPersistence();
export default persistence;
